public class Roman {
    private static final int[] V = {1000,500,100,50,10,5,1};
    private static final String[] S = {"M","D","C","L","X","V","I"};
    public static String toRoman(int n) {
        if (n < 1 || n > 3999) throw new IllegalArgumentException("range");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < V.length; i++) while (n >= V[i]) { sb.append(S[i]); n -= V[i]; }
        return sb.toString();
    }
}

