import java.util.*;
public class WordFreq {
    public static Map<String, Integer> count(String text) {
        Map<String, Integer> m = new TreeMap<>();
        for (String w : text.toLowerCase().split("[^a-z']+")) {
            if (w.isEmpty()) continue;
            m.merge(w, 1, Integer::sum);
        }
        return m;
    }
}

