public class Collatz {
    public static int steps(long n) {
        if (n < 1) throw new IllegalArgumentException("n < 1");
        int s = 0;
        while (n != 1) { n = (n % 2 == 0) ? n / 2 : 3 * n + 1; s++; }
        return s;
    }
}

