reference.Sieve.java:
import java.util.*;
public class Sieve {
    public static List<Integer> primesUpTo(int n) {
        List<Integer> out = new ArrayList<>();
        if (n < 2) return out;
        boolean[] comp = new boolean[n + 1];
        for (int i = 2; i <= n; i++) {
            if (comp[i]) continue;
            out.add(i);
            for (long j = (long) i * i; j <= n; j += i) comp[(int) j] = true;
        }
        return out;
    }
}

