reference.Rot.java:
public class Rot {
    public static void rotate(int[] a, int k) {
        int n = a.length;
        if (n == 0) return;
        k = ((k % n) + n) % n;
        rev(a, 0, n - 1); rev(a, 0, k - 1); rev(a, k, n - 1);
    }
    private static void rev(int[] a, int i, int j) { while (i < j) { int t = a[i]; a[i++] = a[j]; a[j--] = t; } }
}

