public class Lis {
    public static int length(int[] a) {
        int[] t = new int[a.length]; int n = 0;
        for (int x : a) {
            int lo = 0, hi = n;
            while (lo < hi) { int m = (lo + hi) >>> 1; if (t[m] < x) lo = m + 1; else hi = m; }
            t[lo] = x; if (lo == n) n++;
        }
        return n;
    }
}

