import java.util.*;
public class People {
    public static List<Person> byName(List<Person> ps) {
        List<Person> c = new ArrayList<>(ps);
        c.sort(Comparator.comparing(Person::name));
        return c;
    }
    public static List<Person> byAgeThenName(List<Person> ps) {
        List<Person> c = new ArrayList<>(ps);
        c.sort(Comparator.comparingInt(Person::age).thenComparing(Person::name));
        return c;
    }
    public static Map<String, Person> oldestPerCity(List<Person> ps) {
        Map<String, Person> m = new TreeMap<>();
        for (Person p : ps) m.merge(p.city(), p, (a, b) -> b.age() > a.age() ? b : a);
        return m;
    }
}

