            case "+": return a + b;
            case "-": return a - b;
            case "*": return a * b;
            case "/":
                if (b == 0) throw new ArithmeticException("division by zero");
                return a / b;
            case "^": return Math.pow(a, b);
            case "%":
                if (b == 0) throw new ArithmeticException("division by zero");
                return a % b;
            case "max": return Math.max(a, b);
            case "min": return Math.min(a, b);
            default: throw new IllegalArgumentException("unknown op " + op);
        }
    }
}

