import java.util.*;
public class Logger {
    private final List<String> lines = new ArrayList<>();
    private final Map<Level, Integer> counts = new EnumMap<>(Level.class);
    private Level min = Level.DEBUG;
    public void setMinLevel(Level l) { min = l; }
    public void log(Level l, String msg) {
        if (l.compareTo(min) < 0) return;
        lines.add("[" + l + "] " + msg);
        counts.merge(l, 1, Integer::sum);
    }
    public void debug(String m) { log(Level.DEBUG, m); }
    public void info(String m) { log(Level.INFO, m); }
    public void warn(String m) { log(Level.WARN, m); }
    public void error(String m) { log(Level.ERROR, m); }
    public int count(Level l) { return counts.getOrDefault(l, 0); }
    public List<String> lines() { return lines; }
}

