import java.util.*;
public class Inventory {
    private final Map<String, Product> products = new LinkedHashMap<>();
    public void add(Product p) { products.merge(p.sku(), p, (a, b) -> new Product(a.sku(), a.name(), a.qty() + b.qty())); }
    public void remove(String sku, int n) {
        if (n <= 0) throw new IllegalArgumentException("n");
        Product p = products.get(sku);
        if (p == null) throw new NoSuchElementException(sku);
        if (n > p.qty()) throw new IllegalStateException("insufficient stock");
        products.put(sku, new Product(sku, p.name(), p.qty() - n));
    }
    public List<String> lowStock(int threshold) {
        List<String> out = new ArrayList<>();
        for (Product p : products.values()) if (p.qty() < threshold) out.add(p.sku());
        return out;
    }
    public int qty(String sku) { Product p = products.get(sku); return p == null ? 0 : p.qty(); }
}

