public class Parser {
    private final String s; private int p; private final java.util.Map<String, Long> vars;
    private Parser(String s, java.util.Map<String, Long> vars) { this.s = s; this.vars = vars; }
    public static long eval(String s) { return eval(s, java.util.Map.of()); }
    public static long eval(String s, java.util.Map<String, Long> vars) {
        Parser q = new Parser(s, vars); long v = q.expr(); q.ws();
        if (q.p != s.length()) throw new IllegalArgumentException("unexpected input at " + q.p);
        return v;
    }
    private void ws() { while (p < s.length() && s.charAt(p) == ' ') p++; }
    private long expr() {
        long v = term();
        while (true) {
            ws();
            if (p < s.length() && s.charAt(p) == '+') { p++; v += term(); }
            else if (p < s.length() && s.charAt(p) == '-') { p++; v -= term(); }
            else return v;
        }
    }
    private long term() {
        long v = atom();
        while (true) {
            ws();
            if (p < s.length() && s.charAt(p) == '*') { p++; v *= atom(); }
            else if (p < s.length() && s.charAt(p) == '%') { p++; long d = atom(); if (d == 0) throw new ArithmeticException("% by zero"); v %= d; }
            else if (p < s.length() && s.charAt(p) == '/') { p++; long d = atom(); if (d == 0) throw new ArithmeticException("/ by zero"); v /= d; }
            else return v;
        }
    }
