public class Order {
    public enum State { NEW, PAID, SHIPPED, DELIVERED, CANCELLED }
    private State state = State.NEW;
    private final java.util.List<State> hist = new java.util.ArrayList<>(java.util.List.of(State.NEW));
    private void to(State s) { state = s; hist.add(s); }
    public java.util.List<State> history() { return java.util.Collections.unmodifiableList(hist); }
    public void cancel() {
        if (state != State.NEW && state != State.PAID) throw new IllegalStateException("cannot cancel in " + state);
        to(State.CANCELLED);
    }
    public State state() { return state; }
    public void pay() {
        if (state != State.NEW) throw new IllegalStateException("cannot pay in " + state);
        to(State.PAID);
    }
    public void ship() {
        if (state != State.PAID) throw new IllegalStateException("cannot ship in " + state);
        to(State.SHIPPED);
    }
    public void deliver() {
        if (state != State.SHIPPED) throw new IllegalStateException("cannot deliver in " + state);
        to(State.DELIVERED);
    }
}

