public class IdGen {
    private int next = 1;
    private final String prefix; private final int width;
    public IdGen() { this("ID", 0); }
    public IdGen(String prefix, int width) { this.prefix = prefix; this.width = width; }
    public String peek() { return prefix + String.format("%0" + Math.max(width, 1) + "d", next); }
    public String nextId() { String s = peek(); next++; return s; }
    public void reset(int start) { if (start < 1) throw new IllegalArgumentException("start"); next = start; }
}

